actions.script:
const userId = ec.user.userId || null
visible = false; isPersonal = false; isMine = false; isSelf = false; isDisabled = false; canEdit = false; canDelete = false
isSalesEditor = false; canEditIdentity = false
isContactAdmin = !!userId && (ec.user.hasPermission('CONTACT_ADMIN') || ec.user.isInGroup('BOSS_CONTACT_ADMIN') || ec.user.isInGroup('ADMIN'))
const found = ec.entity.find('mantle.party.PartyDetail').condition('partyId', partyId).one()
if (found != null && (!found.privateOwnerUserId || found.privateOwnerUserId === userId)) {
    visible = true
    party = found.getMap()
    isPersonal = !!found.privateOwnerUserId
    isMine = isPersonal && found.privateOwnerUserId === userId
    isSelf = !!userId && ec.user.userAccount?.partyId === partyId
    isDisabled = found.disabled === 'Y'
    canEdit = !isDisabled && (isMine || (!isPersonal && isContactAdmin))
    // Sales (owner contract, F98): an account editor changes the identity and channels alone (canEditIdentity) of a
    // person of an organization of their scope who is a contact of an account of such an organization, with Commons' own
    // forms; a shared (_NA_) person or account, and a person with a user account (a login's email and name), stay the
    // contact admin's
    if (!canEdit && !isDisabled && !isPersonal && !!userId && found.partyTypeEnumId === 'PtyPerson'
            && !!found.ownerPartyId && found.ownerPartyId !== '_NA_'
            && ec.user.hasPermission('SALES_ACCOUNT_EDIT')
            && ec.entity.find('moqui.security.UserAccount').condition('partyId', partyId).disableAuthz().count() === 0) {
        const sales = ec.resource.script('component://mr-mantle/service/mantle/sales/SalesAccess.js')
        const salesScope = sales.scope()
        isSalesEditor = !!salesScope.capabilities.accountEdit && sales.covers(salesScope, found.ownerPartyId)
            && sales.contactAccounts(salesScope, partyId).some((account) => !account.shared)
    }
    canEditIdentity = canEdit || isSalesEditor
    if (!isDisabled && isMine) canDelete = true
    else if (!isDisabled && !isPersonal && isContactAdmin && !isSelf) {
        const hasUser = ec.entity.find('moqui.security.UserAccount').condition('partyId', partyId).disableAuthz().count() > 0
        const internal = ec.entity.find('mantle.party.PartyRole').condition('partyId', partyId).condition('roleTypeId', 'OrgInternal').count() > 0
        canDelete = !hasUser && !internal
    }
}
if (!need) return
if (!visible) { ec.message.addError(ec.resource.expand('Contact ${partyId} not found', '', {partyId: partyId})); return }
if ((need === 'edit' && !canEdit) || (need === 'identity' && !canEditIdentity)) {
    ec.message.addError(ec.resource.expand(isDisabled ? 'Contact ${partyId} was merged or deleted' : 'You may not change contact ${partyId}', '', {partyId: partyId}))
} else if (need === 'delete' && !canDelete) {
    ec.message.addError(ec.resource.expand('You may not delete contact ${partyId}', '', {partyId: partyId}))
}

rowList = []
const ids = Array.from(new Set(Array.from(partyIdList || []).map((id) => String(id)).filter((id) => id)))
if (!ids.length) return
const userId = ec.user.userId || null
const cf = ec.entity.conditionFactory
const current = cf.makeConditionDate('fromDate', 'thruDate', null)
const mineOrDirectory = cf.makeCondition([cf.makeCondition('privateOwnerUserId', 'equals', null),
    cf.makeCondition('privateOwnerUserId', 'equals', userId)], 'or')
const byId = new Map()
for (let start = 0; start < ids.length; start += 200) {
    const chunk = ids.slice(start, start + 200)
    for (const party of ec.entity.find('mantle.party.PartyDetail').condition(cf.makeCondition('partyId', 'in', chunk))
            .condition(mineOrDirectory).list()) {
        if (party.disabled === 'Y') continue
        byId.set(party.partyId, party.getMap())
    }
}
const shown = ids.filter((id) => byId.has(id))
if (!shown.length) return
const group = (list, key) => {
    const map = new Map()
    for (const item of list) { const k = item[key]; if (!map.has(k)) map.set(k, []); map.get(k).push(item) }
    return map
}
const rank = (order, purposeId) => { const index = order.indexOf(purposeId); return index < 0 ? order.length : index }
const emails = group(Array.from(ec.entity.find('mantle.party.contact.PartyContactMechInfo').condition(cf.makeCondition('partyId', 'in', shown))
        .condition('contactMechTypeEnumId', 'CmtEmailAddress').condition(current).orderBy('fromDate').list()).map((row) => row.getMap()), 'partyId')
const phones = group(Array.from(ec.entity.find('mantle.party.contact.PartyContactMechTelecomNumber').condition(cf.makeCondition('partyId', 'in', shown))
        .condition(current).orderBy('fromDate').list()).map((row) => row.getMap()), 'partyId')
const rels = group(Array.from(ec.entity.find('mantle.party.PartyRelationship').condition(cf.makeCondition('fromPartyId', 'in', shown))
        .condition(cf.makeCondition('relationshipTypeEnumId', 'in', ['PrtContact', 'PrtEmployee'])).condition(current)
        .orderBy('-fromDate').list()).map((row) => row.getMap()), 'fromPartyId')
const orgIds = Array.from(new Set(Array.from(rels.values()).flat().map((rel) => rel.toPartyId)))
const orgNames = new Map()
if (orgIds.length) for (const org of ec.entity.find('mantle.party.PartyDetail').condition(cf.makeCondition('partyId', 'in', orgIds))
        .condition(mineOrDirectory).list()) orgNames.set(org.partyId, org.organizationName || org.pseudoId || org.partyId)
const faces = new Set(Array.from(ec.entity.find('mantle.party.PartyContent').condition(cf.makeCondition('partyId', 'in', shown))
        .condition('partyContentTypeEnumId', 'PcntFaceImage').selectField('partyId').list()).map((row) => row.partyId))
// the star of the user's default book (find nothing when the user has none)
const favorites = new Set()
if (userId) {
    const book = ec.entity.find('mantle.party.contact.ContactBook').condition('ownerUserId', userId).condition('visibilityEnumId', 'CbvPersonal')
            .condition('isDefault', 'Y').one()
    if (book != null) for (const row of ec.entity.find('mantle.party.contact.ContactBookParty').condition('contactBookId', book.contactBookId)
            .condition(cf.makeCondition('partyId', 'in', shown)).condition('isFavorite', 'Y').condition(current).list()) favorites.add(row.partyId)
}
const phoneText = (tn) => [tn.countryCode ? '+' + tn.countryCode : null, tn.areaCode, tn.contactNumber].filter((part) => part).join(' ')
for (const id of shown) {
    const party = byId.get(id)
    const isOrg = party.partyTypeEnumId === 'PtyOrganization'
    const name = (ec.resource.expand('PartyNameOnlyTemplate', '', party) || '').trim() || party.pseudoId || id
    const email = (emails.get(id) || []).slice().sort((a, b) => rank(['EmailPrimary'], a.contactMechPurposeId) - rank(['EmailPrimary'], b.contactMechPurposeId))[0]
    const phone = (phones.get(id) || []).slice().sort((a, b) => rank(['PhonePrimary', 'PhoneMobile'], a.contactMechPurposeId)
            - rank(['PhonePrimary', 'PhoneMobile'], b.contactMechPurposeId))[0]
    const rel = isOrg ? null : (rels.get(id) || []).find((candidate) => orgNames.has(candidate.toPartyId))
    const organizationName = isOrg ? null : (rel ? orgNames.get(rel.toPartyId) : null)
    const jobTitle = rel ? (rel.relationshipName || null) : null
    rowList.push({partyId: id, pseudoId: party.pseudoId || id, partyTypeEnumId: party.partyTypeEnumId, isOrganization: isOrg, name: name,
        sortName: String(isOrg ? name : (party.firstName || party.lastName || name)).toLowerCase(),
        organizationName: organizationName, organizationPartyId: rel ? rel.toPartyId : null, jobTitle: jobTitle,
        subtitle: isOrg ? ec.l10n.localize('Organization') : [jobTitle, organizationName].filter((part) => part).join(' · '),
        emailAddress: email ? email.infoString : null, phone: phone ? phoneText(phone) : null,
        isPersonal: !!party.privateOwnerUserId, hasFaceImage: faces.has(id), isFavorite: favorites.has(id)})
}

const L = (text) => ec.l10n.localize(text)
const userId = ec.user.userId || null
const myPartyId = ec.user.userAccount?.partyId || null
const cf = ec.entity.conditionFactory
const max = Math.max(1, Math.min(200, Number(limit || 50)))
const words = text ? String(text).trim() : ''
const first = letter ? String(letter).trim().substring(0, 1).toUpperCase() : ''
rowList = []
rowCount = 0
hasMore = false
contactBook = null
contactBookList = Array.from(ec.service.sync().name('mantle.party.ContactBookServices.get#UserContactBooks').call()?.contactBookList || [])
const books = new Map(contactBookList.map((book) => [book.contactBookId, book]))
scopeOptions = [{key: 'all', text: L('All contacts')}, {key: 'mine', text: L('My contacts')}, {key: 'directory', text: L('Directory')}]
        .concat(contactBookList.map((book) => ({key: book.contactBookId, text: book.contactBookName + (book.isOwner ? '' : ' · ' + L('shared'))})))
        .concat([{key: 'recent', text: L('Recently contacted')}, {key: 'ungrouped', text: L('Not in a group')}])
if (!['all', 'mine', 'directory', 'recent', 'ungrouped'].includes(scope) && !books.has(scope)) scope = 'all'

const digits = words.replace(/\D/g, '')
const isPhone = digits.length >= 3 && !/[A-Za-z@]/.test(words)
// one find#Party: anyField matches the text against the names (first and last in either order), a current email,
// a phone by its digits and the people of an organization of that name, as substrings (leadingWildcard, as the
// books' find); the letter a name that starts with it (combinedName also takes a last name, which the rows leave
// out below), so with a letter the count is the rows'
const findParties = (base) => {
    const params = Object.assign({pageSize: first ? max * 3 : max, pageIndex: 0, orderByField: 'firstName,organizationName'}, base)
    if (words) Object.assign(params, {anyField: words, leadingWildcard: true})
    if (first) params.combinedName = first
    const out = ec.service.sync().name('mantle.party.PartyServices.find#Party').parameters(params).call()
    if (ec.message.hasError()) return {ids: [], count: 0}
    return {ids: Array.from(out.partyIdList || []), count: Number(out.partyIdListCount || 0)}
}
const bookMembers = (bookId, groupId) => {
    const out = ec.service.sync().name('mantle.party.ContactBookServices.find#ContactBookParties').parameters({contactBookId: bookId,
        contactBookGroupId: groupId || null, text: words || null, pageNoLimit: true}).call()
    if (ec.message.hasError()) return []
    return Array.from(out?.contactList || [])
}

let ids = []
let total = null
if (scope === 'all' || scope === 'directory') {
    // the directory is the parties with a role (customer, supplier, employee, contact, account, ...); a personal contact has none
    const found = findParties(scope === 'directory' ? {personalContacts: 'exclude', hasRole: true} : {hasRole: true})
    ids = found.ids || []
    total = found.count
} else if (scope === 'mine') {
    const found = findParties({personalContacts: 'only'})
    ids = (found.ids || []).slice()
    for (const book of contactBookList.filter((entry) => entry.isOwner)) for (const member of bookMembers(book.contactBookId)) ids.push(member.partyId)
} else if (scope === 'recent') {
    if (myPartyId) {
        const since = new Date(Number(String(ec.user.nowTimestamp)) - 90 * 86400000)
        const events = ec.entity.find('mantle.party.communication.CommunicationEvent')
                .condition(cf.makeCondition([cf.makeCondition('fromPartyId', 'equals', myPartyId), cf.makeCondition('toPartyId', 'equals', myPartyId)], 'or'))
                .condition(cf.makeCondition('entryDate', 'greater-equals', since)).selectField('fromPartyId,toPartyId,entryDate')
                .orderBy('-entryDate').limit(500).list()
        for (const event of events) for (const other of [event.fromPartyId, event.toPartyId]) if (other && other !== myPartyId) ids.push(other)
    }
} else if (scope === 'ungrouped') {
    const grouped = new Set()
    const members = []
    for (const book of contactBookList) for (const member of bookMembers(book.contactBookId)) {
        members.push(member.partyId)
        if ((member.groupList || []).length) grouped.add(member.partyId)
    }
    ids = members.filter((id) => !grouped.has(id))
} else {
    contactBook = books.get(scope)
    ids = bookMembers(scope, contactBookGroupId).map((member) => member.partyId)
}

ids = Array.from(new Set(ids)).filter((id) => id !== '_NA_')
let rows = ids.length ? Array.from(ec.service.sync().name('ironstone.commons.ContactServices.get#ContactRows').parameters({partyIdList: ids}).call()?.rowList || []) : []
// the text and letter in the scopes whose finds do not take them
const lower = words.toLowerCase()
if (words && (scope === 'recent' || scope === 'ungrouped')) {
    rows = rows.filter((row) => [row.name, row.organizationName, row.emailAddress].some((value) => value && String(value).toLowerCase().includes(lower))
            || (isPhone && row.phone && String(row.phone).replace(/\D/g, '').includes(digits)))
}
if (first) rows = rows.filter((row) => String(row.name || '').toUpperCase().startsWith(first))
if (scope !== 'recent') rows.sort((a, b) => a.sortName.localeCompare(b.sortName) || a.partyId.localeCompare(b.partyId))
rowCount = Math.max(rows.length, total != null && !first ? total : 0)
hasMore = rows.length > max || rowCount > max
rowList = rows.slice(0, max)

found = false
const L = (text) => ec.l10n.localize(text)
const access = ec.service.sync().name('ironstone.commons.ContactServices.check#ContactAccess').parameters({partyId: partyId}).call() || {}
if (!access.visible) return
found = true
const userId = ec.user.userId || null
const cf = ec.entity.conditionFactory
const now = Number(String(ec.user.nowTimestamp))
const current = cf.makeConditionDate('fromDate', 'thruDate', null)
const millis = (value) => value == null || value === '' ? null : Number(String(value))
const isExpired = (row) => millis(row.thruDate) != null && millis(row.thruDate) <= now
const fmtDate = (value) => value == null || value === '' ? null : ec.l10n.format(value, 'yyyy-MM-dd')
// a date field (birthDate) reaches the script as the epoch millis of its UTC midnight: its UTC day, as export#Contacts reads it
const dayOf = (value) => {
    if (value == null || value === '') return null
    const text = String(value)
    return /^-?\d+$/.test(text) ? new Date(Number(text)).toISOString().substring(0, 10) : text.substring(0, 10)
}
const party = access.party
const isOrg = party.partyTypeEnumId === 'PtyOrganization'
const visibleParty = (id) => {
    if (!id) return null
    const other = ec.entity.find('mantle.party.PartyDetail').condition('partyId', id).one()
    return other != null && (!other.privateOwnerUserId || other.privateOwnerUserId === userId) ? other : null
}
const nameOf = (other) => (ec.resource.expand('PartyNameOnlyTemplate', '', other) || '').trim() || other.pseudoId || other.partyId
const purposes = {}
const purposeText = (id) => {
    if (!id) return ''
    if (purposes[id] === undefined) {
        const purpose = ec.entity.find('mantle.party.contact.ContactMechPurpose').condition('contactMechPurposeId', id).useCache(true).one()
        // without the kind the row already shows: "Email - Primary Address" is "Primary Address"
        purposes[id] = purpose ? String(purpose.description || id).replace(/^[A-Za-z ]+ - /, '') : id
    }
    return purposes[id]
}
const enumText = (id) => {
    if (!id) return ''
    const value = ec.entity.find('moqui.basic.Enumeration').condition('enumId', id).useCache(true).one()
    return value ? (value.description || id) : id
}

mergedToPartyId = party.mergedToPartyId || null
record = {partyId: party.partyId, pseudoId: party.pseudoId || party.partyId, partyTypeEnumId: party.partyTypeEnumId, isOrganization: isOrg,
    name: nameOf(party), firstName: party.firstName ?? null, middleName: party.middleName ?? null, lastName: party.lastName ?? null,
    nickname: party.nickname ?? null, personalTitle: party.personalTitle ?? null, suffix: party.suffix ?? null,
    birthDate: dayOf(party.birthDate), organizationName: party.organizationName ?? null, comments: party.comments ?? null,
    kindLabel: L(isOrg ? 'Organization' : 'Person'), hasFaceImage: ec.entity.find('mantle.party.PartyContent').condition('partyId', partyId)
            .condition('partyContentTypeEnumId', 'PcntFaceImage').count() > 0}
const accessOut = {visible: true, isPersonal: !!access.isPersonal, isMine: !!access.isMine, isContactAdmin: !!access.isContactAdmin,
    isSelf: !!access.isSelf, isDisabled: !!access.isDisabled, canEdit: !!access.canEdit, canEditIdentity: !!access.canEditIdentity,
    canDelete: !!access.canDelete}
context.put('access', accessOut)

roleList = Array.from(ec.entity.find('mantle.party.PartyRole').condition('partyId', partyId).list()).map((role) => {
    const roleType = ec.entity.find('mantle.party.RoleType').condition('roleTypeId', role.roleTypeId).useCache(true).one()
    return {roleTypeId: role.roleTypeId, description: roleType ? (roleType.description || role.roleTypeId) : role.roleTypeId}
})

// the primary email, phone, website and address as Mantle's contact info has them (get#PartyContactInfo: the latest
// of each kind's Primary purpose; a phone or email the primary address names when the party has no primary one); a
// failure is logged and the rows show without
const primary = {}
ec.message.pushErrors()
try {
    const info = ec.service.sync().name('mantle.party.ContactServices.get#PartyContactInfo').parameters({partyId: partyId,
        postalContactMechPurposeId: 'PostalPrimary', telecomContactMechPurposeId: 'PhonePrimary', emailContactMechPurposeId: 'EmailPrimary',
        webContactMechPurposeId: 'WebUrlPrimary'}).call()
    if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    if (info?.postalContactMechId && info.postalAddress) primary.postal = info.postalContactMechId
    if (info?.telecomContactMechId && info.telecomNumber) primary.phone = {contactMechId: info.telecomContactMechId, telecomNumber: info.telecomNumber}
    if (info?.emailContactMechId && info.emailAddress) primary.email = {contactMechId: info.emailContactMechId, value: String(info.emailAddress)}
    if (info?.webContactMechId && info.webAddress) primary.web = {contactMechId: info.webContactMechId, value: String(info.webAddress)}
} catch (err) {
    ec.logger.warn(`Contact ${partyId}: the primary contact information was not read, the rows show without it: ${err && err.message ? err.message : err}`)
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}

// contact information: one row per address or number with its purposes
let infoFind = ec.entity.find('mantle.party.contact.PartyContactMechInfo').condition('partyId', partyId)
        .condition(cf.makeCondition('contactMechTypeEnumId', 'not-equals', 'CmtPostalAddress')).orderBy('contactMechTypeEnumId,fromDate')
if (!showExpired) infoFind = infoFind.condition(current)
const infos = Array.from(infoFind.list()).map((row) => row.getMap())
expiredCount = ec.entity.find('mantle.party.contact.PartyContactMech').condition('partyId', partyId)
        .condition(cf.makeCondition('thruDate', 'less-equals', new Date(now))).count()
const kinds = {CmtEmailAddress: 'email', CmtTelecomNumber: 'phone', CmtWebAddress: 'web'}
const kindLabels = {email: L('Email'), phone: L('Phone'), web: L('Website'), other: L('Other')}
const byMech = new Map()
contactMechList = []
for (const row of infos) {
    let entry = byMech.get(row.contactMechId)
    if (entry == null) {
        const kind = kinds[row.contactMechTypeEnumId] || 'other'
        let value = row.infoString
        let telecom = null
        if (kind === 'phone') {
            const tn = ec.entity.find('mantle.party.contact.TelecomNumber').condition('contactMechId', row.contactMechId).one()
            if (tn != null) {
                telecom = {countryCode: tn.countryCode ?? null, areaCode: tn.areaCode ?? null, contactNumber: tn.contactNumber ?? null}
                value = [tn.countryCode ? '+' + tn.countryCode : null, tn.areaCode, tn.contactNumber].filter((part) => part).join(' ')
            }
        }
        entry = {contactMechId: row.contactMechId, kind: kind, kindLabel: kindLabels[kind], contactMechTypeEnumId: row.contactMechTypeEnumId,
            typeLabel: kind === 'other' ? enumText(row.contactMechTypeEnumId) : kindLabels[kind], value: value ? String(value) : '',
            infoString: row.infoString ?? null, telecom: telecom, purposeList: [], purposeText: '', expired: true,
            allowSolicitation: row.allowSolicitation ?? null, href: null}
        if (kind === 'email' && value) entry.href = 'mailto:' + value
        else if (kind === 'web' && value) entry.href = /^https?:\/\//i.test(String(value)) ? String(value) : null
        else if (kind === 'phone' && value) entry.href = 'tel:' + String(value).replace(/[^\d+]/g, '')
        byMech.set(row.contactMechId, entry)
        contactMechList.push(entry)
    }
    const expired = isExpired(row)
    if (!expired) entry.expired = false
    entry.purposeList.push({contactMechPurposeId: row.contactMechPurposeId ?? null, description: purposeText(row.contactMechPurposeId),
        fromDate: millis(row.fromDate), expired: expired})
}
for (const entry of contactMechList) entry.purposeText = entry.purposeList.filter((p) => entry.expired || !p.expired)
        .map((p) => p.description).filter((text) => text).join(', ')
// the primary of each kind first; one the party has only through its primary address is a row of its own, read only
for (const kind of ['email', 'phone', 'web']) {
    const main = primary[kind]
    if (!main) continue
    let entry = contactMechList.find((mech) => mech.contactMechId === main.contactMechId)
    if (entry == null) {
        const tn = main.telecomNumber
        const value = kind === 'phone' ? [tn.countryCode ? '+' + tn.countryCode : null, tn.areaCode, tn.contactNumber].filter((part) => part).join(' ') : main.value
        entry = {contactMechId: main.contactMechId, kind: kind, kindLabel: kindLabels[kind], typeLabel: kindLabels[kind],
            contactMechTypeEnumId: {email: 'CmtEmailAddress', phone: 'CmtTelecomNumber', web: 'CmtWebAddress'}[kind], value: value,
            infoString: kind === 'phone' ? null : value, telecom: kind === 'phone' ? {countryCode: tn.countryCode ?? null, areaCode: tn.areaCode ?? null,
                contactNumber: tn.contactNumber ?? null} : null, purposeList: [], purposeText: L('Of the primary address'), expired: false,
            allowSolicitation: null, readOnly: true,
            href: kind === 'email' ? 'mailto:' + value : kind === 'phone' ? 'tel:' + String(value).replace(/[^\d+]/g, '') : (/^https?:\/\//i.test(value) ? value : null)}
        contactMechList.push(entry)
    }
    entry.isPrimary = true
}
const kindOrder = {email: 0, phone: 1, web: 2, other: 3}
contactMechList = contactMechList.map((entry, index) => ({entry, index})).sort((a, b) => (kindOrder[a.entry.kind] - kindOrder[b.entry.kind])
        || ((b.entry.isPrimary ? 1 : 0) - (a.entry.isPrimary ? 1 : 0)) || (a.index - b.index)).map((item) => item.entry)
for (const entry of contactMechList) { entry.isPrimary = !!entry.isPrimary; entry.readOnly = !!entry.readOnly }

// addresses
let addressFind = ec.entity.find('mantle.party.contact.PartyContactMechPostalAddress').condition('partyId', partyId).orderBy('fromDate')
if (!showExpired) addressFind = addressFind.condition(current)
const byAddress = new Map()
addressList = []
for (const row of addressFind.list()) {
    let entry = byAddress.get(row.contactMechId)
    if (entry == null) {
        const country = row.countryGeoId ? ec.entity.find('moqui.basic.Geo').condition('geoId', row.countryGeoId).useCache(true).one() : null
        const region = row.stateGeoCodeAlpha2 || row.stateGeoName || ''
        const lines = [row.address1, row.address2, row.unitNumber ? '#' + row.unitNumber : null,
            [row.city, [region, row.postalCode].filter((part) => part).join(' ')].filter((part) => part).join(', '), country ? country.geoName : null]
                .filter((part) => part)
        entry = {contactMechId: row.contactMechId, address1: row.address1 ?? null, address2: row.address2 ?? null, unitNumber: row.unitNumber ?? null,
            city: row.city ?? null, stateProvinceGeoId: row.stateProvinceGeoId ?? null, postalCode: row.postalCode ?? null,
            countryGeoId: row.countryGeoId ?? null, text: lines.join('\n'), oneLine: lines.join(', '), purposeList: [], purposeText: '', expired: true}
        byAddress.set(row.contactMechId, entry)
        addressList.push(entry)
    }
    const expired = isExpired(row)
    if (!expired) entry.expired = false
    entry.purposeList.push({contactMechPurposeId: row.contactMechPurposeId ?? null, description: purposeText(row.contactMechPurposeId),
        fromDate: millis(row.fromDate), expired: expired})
}
for (const entry of addressList) entry.purposeText = entry.purposeList.filter((p) => entry.expired || !p.expired)
        .map((p) => p.description).filter((text) => text).join(', ')
for (const entry of addressList) entry.isPrimary = !!primary.postal && entry.contactMechId === primary.postal
addressList = addressList.map((entry, index) => ({entry, index})).sort((a, b) => ((b.entry.isPrimary ? 1 : 0) - (a.entry.isPrimary ? 1 : 0))
        || (a.index - b.index)).map((item) => item.entry)

// relationships, both ways, to parties the user may see; a person's organizations and titles among them
relationshipList = []
organizationList = []
let relFind = ec.entity.find('mantle.party.PartyRelationship').condition(cf.makeCondition([cf.makeCondition('fromPartyId', 'equals', partyId),
    cf.makeCondition('toPartyId', 'equals', partyId)], 'or')).orderBy('-fromDate')
if (!showExpired) relFind = relFind.condition(current)
for (const rel of relFind.list()) {
    const outgoing = rel.fromPartyId === partyId
    const other = visibleParty(outgoing ? rel.toPartyId : rel.fromPartyId)
    if (other == null) continue
    const type = enumText(rel.relationshipTypeEnumId)
    const row = {partyRelationshipId: rel.partyRelationshipId, relationshipTypeEnumId: rel.relationshipTypeEnumId,
        otherPartyId: other.partyId, otherName: nameOf(other), otherIsOrganization: other.partyTypeEnumId === 'PtyOrganization',
        otherIsPersonal: !!other.privateOwnerUserId, outgoing: outgoing,
        // the type describes the from party: Joe is a Contact of Acme (outgoing), Manager: Bob (incoming)
        description: outgoing ? ec.resource.expand('${type} of ${name}', '', {type: type, name: nameOf(other)})
            : ec.resource.expand('${type}: ${name}', '', {type: type, name: nameOf(other)}),
        relationshipName: rel.relationshipName ?? null, fromDate: fmtDate(rel.fromDate), thruDate: fmtDate(rel.thruDate), expired: isExpired(rel)}
    relationshipList.push(row)
    if (!isOrg && outgoing && !row.expired && row.otherIsOrganization && ['PrtContact', 'PrtEmployee'].includes(rel.relationshipTypeEnumId))
        organizationList.push({partyRelationshipId: rel.partyRelationshipId, organizationPartyId: other.partyId, organizationName: row.otherName,
            jobTitle: rel.relationshipName ?? null, relationshipTypeEnumId: rel.relationshipTypeEnumId, typeLabel: type})
}

// the user's books that hold the party, with their groups; the others the user may edit
bookList = []
otherBookList = []
const userBooks = Array.from(ec.service.sync().name('mantle.party.ContactBookServices.get#UserContactBooks').call()?.contactBookList || [])
for (const book of userBooks) {
    const member = ec.entity.find('mantle.party.contact.ContactBookParty').condition('contactBookId', book.contactBookId)
            .condition('partyId', partyId).condition(current).list()
    const canEditBook = ['CbpEdit', 'CbpManage'].includes(book.permissionEnumId)
    if (!member.length) {
        // a personal contact goes only in its owner's personal books
        if (canEditBook && (!accessOut.isPersonal || book.isOwner)) otherBookList.push({contactBookId: book.contactBookId,
            contactBookName: book.contactBookName, isOwner: book.isOwner, groupList: book.groupList || []})
        continue
    }
    const groupIds = (book.groupList || []).map((group) => group.contactBookGroupId)
    const inGroups = new Set(groupIds.length ? Array.from(ec.entity.find('mantle.party.contact.ContactBookGroupParty')
            .condition(cf.makeCondition('contactBookGroupId', 'in', groupIds)).condition('partyId', partyId).list()).map((row) => row.contactBookGroupId) : [])
    bookList.push({contactBookId: book.contactBookId, contactBookName: book.contactBookName, isOwner: book.isOwner, isDefault: book.isDefault,
        canEdit: canEditBook, isFavorite: member[0].isFavorite === 'Y',
        groupList: (book.groupList || []).map((group) => ({contactBookGroupId: group.contactBookGroupId, groupName: group.groupName,
            member: inGroups.has(group.contactBookGroupId)})),
        memberGroupText: (book.groupList || []).filter((group) => inGroups.has(group.contactBookGroupId)).map((group) => group.groupName).join(', ')})
}

noteList = Array.from(ec.entity.find('mantle.party.PartyNote').condition('partyId', partyId).orderBy('-noteDate').limit(50).list()).map((note) => {
    const user = note.userId ? ec.entity.find('moqui.security.UserAccount').condition('userId', note.userId).useCache(true).disableAuthz().one() : null
    return {noteDate: millis(note.noteDate), noteDateText: ec.l10n.format(note.noteDate, 'yyyy-MM-dd HH:mm'), noteText: note.noteText ?? '',
        userName: user ? (user.userFullName || user.username) : '', mine: !!userId && note.userId === userId}
})

// the employee directory card, read only (the Employee 360 is People's)
employeeCard = null
if (!isOrg && roleList.some((role) => role.roleTypeId === 'Employee')) {
    const employment = Array.from(ec.entity.find('mantle.party.PartyRelationship').condition('fromPartyId', partyId)
            .condition('relationshipTypeEnumId', 'PrtEmployee').condition(current).orderBy('-fromDate').list())
    const rel = employment.find((candidate) => visibleParty(candidate.toPartyId) != null)
    let position = rel ? (rel.relationshipName || null) : null
    if (rel) {
        const empl = ec.entity.find('mantle.humanres.employment.Employment').condition('partyRelationshipId', rel.partyRelationshipId).one()
        const pos = empl?.emplPositionId ? ec.entity.find('mantle.humanres.position.EmplPosition').condition('emplPositionId', empl.emplPositionId).one() : null
        if (pos?.description) position = pos.description
    }
    const managerRel = Array.from(ec.entity.find('mantle.party.PartyRelationship').condition('toPartyId', partyId)
            .condition('relationshipTypeEnumId', 'PrtManager').condition(current).orderBy('-fromDate').list())
            .map((candidate) => visibleParty(candidate.fromPartyId)).find((other) => other != null)
    const org = rel ? visibleParty(rel.toPartyId) : null
    employeeCard = {organizationPartyId: org ? org.partyId : null, organizationName: org ? nameOf(org) : null, position: position,
        managerPartyId: managerRel ? managerRel.partyId : null, managerName: managerRel ? nameOf(managerRel) : null,
        sinceDate: rel ? fmtDate(rel.fromDate) : null}
}
record.personalBookText = accessOut.isPersonal ? bookList.filter((book) => book.isOwner).map((book) => book.contactBookName).join(', ') : null
record.favoriteBookId = (bookList.find((book) => book.isDefault) || bookList.find((book) => book.isOwner) || {}).contactBookId || null
record.isFavorite = bookList.some((book) => book.isDefault && book.isFavorite)
record.primaryEmail = (contactMechList.find((mech) => mech.kind === 'email' && mech.isPrimary && !mech.expired)
        || contactMechList.find((mech) => mech.kind === 'email' && !mech.expired) || {}).value || null
const org0 = organizationList[0]
record.subtitle = isOrg ? L('Organization') : [org0 ? org0.jobTitle : null, org0 ? org0.organizationName : null].filter((part) => part).join(' · ')

eventList = []; taskList = []; requestList = []
const access = ec.service.sync().name('ironstone.commons.ContactServices.check#ContactAccess').parameters({partyId: partyId, need: 'view'}).call()
if (ec.message.hasError()) return
const cf = ec.entity.conditionFactory
const now = Number(String(ec.user.nowTimestamp))
const day = (millis) => ec.l10n.format(String(millis), 'yyyy-MM-dd')
const status = (id) => {
    if (!id) return ''
    const item = ec.entity.find('moqui.basic.StatusItem').condition('statusId', id).useCache(true).one()
    return item ? (item.description || id) : id
}
const role = (id) => {
    if (!id) return ''
    const item = ec.entity.find('mantle.party.RoleType').condition('roleTypeId', id).useCache(true).one()
    return item ? (item.description || id) : id
}
if (tab === 'calendar') {
    const out = ec.service.sync().name('mantle.work.EventServices.get#FullCalendarData').parameters({partyId: partyId,
        start: day(now - 30 * 86400000), end: day(now + 90 * 86400000), includeAllUsers: false, showDeclined: false}).call()
    if (ec.message.hasError()) { ec.logger.warn(`Contact ${partyId} calendar not shown: ${ec.message.getErrorsString()}`); ec.message.clearErrors(); return }
    eventList = Array.from(out?.eventList || []).map((event) => ({workEffortId: event.workEffortId, title: String(event.title || '').replace(/ \[[^\]]*\]$/, ''),
        whenText: event.allDay ? String(event.start || '').substring(0, 10) : String(event.start || '').replace('T', ' ').substring(0, 16),
        startMillis: event.startMillis, statusText: status(event.statusId), statusId: event.statusId,
        upcoming: Number(event.startMillis || 0) >= now, url: '/qapps/Commons/Calendar/EventDetail?workEffortId=' + encodeURIComponent(event.workEffortId)}))
    eventList.sort((a, b) => Number(b.startMillis || 0) - Number(a.startMillis || 0))
} else if (tab === 'tasks') {
    const closedIds = ['WeComplete', 'WeClosed', 'WeCancelled']
    const task = (row, roleTypeId) => ({workEffortId: row.workEffortId, workEffortName: row.workEffortName, statusId: row.statusId,
        estimatedCompletionDate: row.estimatedCompletionDate, roleTypeId: roleTypeId, closed: closedIds.includes(row.statusId)})
    const rows = Array.from(ec.entity.find('mantle.work.effort.WorkEffortAndParty').condition('partyId', partyId)
            .condition('workEffortTypeEnumId', 'WetTask').condition(cf.makeConditionDate('fromDate', 'thruDate', null))
            .orderBy('-estimatedCompletionDate').limit(100).list()).map((row) => task(row, row.roleTypeId))
    // tasks linked to the party as a record (WorkEffortRecord) have no role
    const linkedIds = Array.from(ec.entity.find('mantle.work.effort.WorkEffortRecord').condition('recordEntityName', 'mantle.party.Party')
            .condition('recordId', partyId).selectField('workEffortId').list()).map((link) => link.workEffortId)
    if (linkedIds.length) rows.push(...Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', linkedIds)
            .condition('workEffortTypeEnumId', 'WetTask').orderBy('-estimatedCompletionDate').limit(100).list()).map((row) => task(row, null)))
    // open ones first, each group undated then latest due; the visibility check stops at the first 100 shown
    const due = (row) => row.estimatedCompletionDate == null ? Infinity : Number(String(row.estimatedCompletionDate))
    rows.sort((a, b) => (a.closed ? 1 : 0) - (b.closed ? 1 : 0) || due(b) - due(a))
    const seen = new Set()
    for (const row of rows) {
        if (taskList.length >= 100) break
        if (seen.has(row.workEffortId)) continue
        seen.add(row.workEffortId)
        const visible = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo').parameters({
            recordEntityName: 'mantle.work.effort.WorkEffort', recordId: row.workEffortId, checkOnly: true}).call()
        if (visible?.recordVisible !== true) continue
        taskList.push({workEffortId: row.workEffortId, workEffortName: row.workEffortName || row.workEffortId, statusText: status(row.statusId),
            closed: row.closed, dueText: row.estimatedCompletionDate ? ec.l10n.format(row.estimatedCompletionDate, 'yyyy-MM-dd') : '',
            roleText: role(row.roleTypeId), url: '/qapps/Commons/Tasks/TaskDetail?workEffortId=' + encodeURIComponent(row.workEffortId)})
    }
} else if (tab === 'requests') {
    const rows = Array.from(ec.entity.find('mantle.request.RequestParty').condition('partyId', partyId)
            .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).orderBy('-fromDate').limit(100).list())
    const seen = new Set()
    for (const row of rows) {
        if (seen.has(row.requestId)) continue
        seen.add(row.requestId)
        // the request under the user's filters
        const request = ec.entity.find('mantle.request.Request').condition('requestId', row.requestId).one()
        // a confidential case is People's alone, on no contact's tab (impl-people P21)
        if (request == null || request.requestTypeEnumId === 'RqtHrCase') continue
        requestList.push({requestId: request.requestId, requestName: request.requestName || request.requestId, statusText: status(request.statusId),
            roleText: role(row.roleTypeId), dateText: request.requestDate ? ec.l10n.format(request.requestDate, 'yyyy-MM-dd') : '',
            url: '/qapps/Commons/Requests/RequestDetail?requestId=' + encodeURIComponent(request.requestId)})
    }
}

const access = ec.service.sync().name('ironstone.commons.ContactServices.check#ContactAccess').parameters({partyId: partyId, need: 'identity'}).call()
if (ec.message.hasError()) return
const isOrg = access.party.partyTypeEnumId === 'PtyOrganization'
const fields = {partyId: partyId}
const text = (value) => value == null ? undefined : (String(value).trim() || null)
const put = (name, value) => { const v = text(value); if (v !== undefined) fields[name] = v }
if (isOrg) {
    put('organizationName', organizationName)
    if (fields.organizationName === null) { ec.message.addError(ec.l10n.localize('An organization needs a name')); return }
} else {
    for (const [name, value] of [['firstName', firstName], ['middleName', middleName], ['lastName', lastName], ['nickname', nickname],
            ['personalTitle', personalTitle], ['suffix', suffix], ['birthDate', birthDate]]) put(name, value)
    const first = fields.firstName !== undefined ? fields.firstName : access.party.firstName
    const last = fields.lastName !== undefined ? fields.lastName : access.party.lastName
    if (!first && !last) { ec.message.addError(ec.l10n.localize('A person needs a first or last name')); return }
}
put('comments', comments)
ec.service.sync().name('mantle.party.PartyServices.update#PartyDetail').parameters(fields).call()

const access = ec.service.sync().name('ironstone.commons.ContactServices.check#ContactAccess').parameters({partyId: partyId, need: 'edit'}).call()
if (ec.message.hasError()) return
const cf = ec.entity.conditionFactory
if (partyRelationshipId) {
    const rel = ec.entity.find('mantle.party.PartyRelationship').condition('partyRelationshipId', partyRelationshipId).one()
    if (rel == null || (rel.fromPartyId !== partyId && rel.toPartyId !== partyId)) { ec.message.addError(ec.l10n.localize('Relationship not found')); return }
    if (thruNow) rel.set('thruDate', ec.user.nowTimestamp)
    else rel.set('relationshipName', jobTitle ? String(jobTitle).trim() : null)
    rel.update()
    return
}
if (!organizationPartyId) { ec.message.addError(ec.l10n.localize('Choose the organization')); return }
const org = ec.service.sync().name('ironstone.commons.ContactServices.check#ContactAccess').parameters({partyId: organizationPartyId}).call()
if (!org?.visible || org.party.partyTypeEnumId !== 'PtyOrganization') {
    ec.message.addError(ec.resource.expand('Organization ${id} not found', '', {id: organizationPartyId})); return }
if (access.isPersonal === false && org.isPersonal) {
    ec.message.addError(ec.l10n.localize('A directory contact cannot work for one of your personal contacts')); return }
const existing = Array.from(ec.entity.find('mantle.party.PartyRelationship').condition('fromPartyId', partyId).condition('toPartyId', organizationPartyId)
        .condition(cf.makeCondition('relationshipTypeEnumId', 'in', ['PrtContact', 'PrtEmployee'])).condition(cf.makeConditionDate('fromDate', 'thruDate', null)).list())
if (existing.length) {
    existing[0].set('relationshipName', jobTitle ? String(jobTitle).trim() : null)
    existing[0].update()
    return
}
ec.service.sync().name('create#mantle.party.PartyRelationship').parameters({relationshipTypeEnumId: 'PrtContact', fromPartyId: partyId,
    toPartyId: organizationPartyId, relationshipName: jobTitle ? String(jobTitle).trim() : null, fromDate: ec.user.nowTimestamp}).call()

const access = ec.service.sync().name('ironstone.commons.ContactServices.check#ContactAccess').parameters({partyId: partyId, need: 'edit'}).call()
if (ec.message.hasError()) return
const other = ec.service.sync().name('ironstone.commons.ContactServices.check#ContactAccess').parameters({partyId: otherPartyId}).call()
if (!other?.visible) { ec.message.addError(ec.resource.expand('Contact ${partyId} not found', '', {partyId: otherPartyId})); return }
if (otherPartyId === partyId) { ec.message.addError(ec.l10n.localize('Choose another contact')); return }
if (!access.isPersonal && other.isPersonal) { ec.message.addError(ec.l10n.localize('A directory contact cannot be related to one of your personal contacts')); return }
const type = ec.entity.find('moqui.basic.Enumeration').condition('enumId', relationshipTypeEnumId).condition('enumTypeId', 'PartyRelationshipType').useCache(true).one()
if (type == null) { ec.message.addError(ec.resource.expand('Unknown relationship type ${id}', '', {id: relationshipTypeEnumId})); return }
partyRelationshipId = ec.service.sync().name('create#mantle.party.PartyRelationship').parameters({relationshipTypeEnumId: relationshipTypeEnumId,
    fromPartyId: reverse ? otherPartyId : partyId, toPartyId: reverse ? partyId : otherPartyId,
    relationshipName: relationshipName ? String(relationshipName).trim() : null, fromDate: ec.user.nowTimestamp}).call()?.partyRelationshipId

ec.service.sync().name('ironstone.commons.ContactServices.check#ContactAccess').parameters({partyId: partyId, need: 'edit'}).call()
if (ec.message.hasError()) return
const textValue = noteText ? String(noteText).trim() : ''
if (noteDate) {
    const note = ec.entity.find('mantle.party.PartyNote').condition('partyId', partyId).condition('noteDate', new Date(Number(String(noteDate)))).one()
    if (note == null || note.userId !== ec.user.userId) { ec.message.addError(ec.l10n.localize('Note not found')); return }
    if (!textValue) { note.delete(); return }
    note.set('noteText', textValue)
    note.update()
    return
}
if (!textValue) { ec.message.addError(ec.l10n.localize('Write the note')); return }
ec.service.sync().name('create#mantle.party.PartyNote').parameters({partyId: partyId, noteDate: ec.user.nowTimestamp, noteText: textValue,
    userId: ec.user.userId}).call()

ec.service.sync().name('ironstone.commons.ContactServices.check#ContactAccess').parameters({partyId: partyId, need: 'identity'}).call()
if (ec.message.hasError()) return
const L = (text) => ec.l10n.localize(text)
const cf = ec.entity.conditionFactory
if (contactMechId && ec.entity.find('mantle.party.contact.PartyContactMech').condition('partyId', partyId).condition('contactMechId', contactMechId)
        .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).count() === 0) { ec.message.addError(L('Contact information not found')); return }
const params = {partyId: partyId}
if (kind === 'email') {
    if (!emailAddress) { ec.message.addValidationError(null, 'emailAddress', null, L('Enter the email address'), null); return }
    Object.assign(params, {emailAddress: String(emailAddress).trim(), emailContactMechId: contactMechId || null,
        emailContactMechPurposeId: contactMechPurposeId || 'EmailPrimary'})
} else if (kind === 'web') {
    let url = webAddress ? String(webAddress).trim() : ''
    if (!url) { ec.message.addValidationError(null, 'webAddress', null, L('Enter the website address'), null); return }
    if (!/^[a-z][a-z0-9+.-]*:/i.test(url)) url = 'https://' + url
    Object.assign(params, {webAddress: url, webContactMechId: contactMechId || null, webContactMechPurposeId: contactMechPurposeId || 'WebUrlPrimary'})
} else if (kind === 'phone') {
    let parts = {countryCode: countryCode || null, areaCode: areaCode || null, contactNumber: contactNumber || null}
    if (phone) {
        let digits = String(phone).replace(/\D/g, '')
        let country = null
        if (String(phone).trim().startsWith('+') && digits.length > 10) { country = digits.substring(0, digits.length - 10); digits = digits.substring(digits.length - 10) }
        else if (digits.length === 11 && digits.startsWith('1')) { country = '1'; digits = digits.substring(1) }
        parts = digits.length === 10 ? {countryCode: country, areaCode: digits.substring(0, 3), contactNumber: digits.substring(3, 6) + '-' + digits.substring(6)}
                : {countryCode: country, areaCode: null, contactNumber: digits}
    }
    if (!parts.contactNumber || String(parts.contactNumber).replace(/\D/g, '').length < 4) {
        ec.message.addValidationError(null, 'phone', null, L('Enter the phone number'), null); return }
    Object.assign(params, parts, {telecomContactMechId: contactMechId || null, telecomContactMechPurposeId: contactMechPurposeId || 'PhonePrimary'})
} else if (kind === 'postal') {
    if (!address1 || !city) { ec.message.addValidationError(null, 'address1', null, L('Enter the street and city'), null); return }
    Object.assign(params, {address1: address1, address2: address2 || null, unitNumber: unitNumber || null, city: city,
        stateProvinceGeoId: stateProvinceGeoId || null, postalCode: postalCode || null, countryGeoId: countryGeoId || null,
        postalContactMechId: contactMechId || null, postalContactMechPurposeId: contactMechPurposeId || 'PostalPrimary'})
} else { ec.message.addError(ec.resource.expand('Unknown kind of contact information ${kind}', '', {kind: kind})); return }
const out = ec.service.sync().name('mantle.party.ContactServices.store#PartyContactInfo').parameters(params).call()
if (ec.message.hasError()) return
contactMechId = out?.emailContactMechId || out?.webContactMechId || out?.telecomContactMechId || out?.postalContactMechId || null

ec.service.sync().name('ironstone.commons.ContactServices.check#ContactAccess').parameters({partyId: partyId, need: 'identity'}).call()
if (ec.message.hasError()) return
const cf = ec.entity.conditionFactory
const rows = Array.from(ec.entity.find('mantle.party.contact.PartyContactMech').condition('partyId', partyId).condition('contactMechId', contactMechId)
        .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).list())
if (!rows.length) { ec.message.addError(ec.l10n.localize('Contact information not found')); return }
if (remove) {
    ec.service.sync().name('mantle.party.ContactServices.delete#PartyContactMech').parameters({partyId: partyId, contactMechId: contactMechId,
        contactMechPurposeId: contactMechPurposeId || null}).call()
    return
}
if (!contactMechPurposeId) { ec.message.addError(ec.l10n.localize('Choose the purpose')); return }
ec.service.sync().name('mantle.party.ContactServices.store#PartyContactMech').parameters({partyId: partyId, contactMechId: contactMechId,
    contactMechPurposeId: contactMechPurposeId, fromDate: ec.user.nowTimestamp}).call()

const L = (text) => ec.l10n.localize(text)
ec.service.sync().name('ironstone.commons.ContactServices.check#ContactAccess').parameters({partyId: partyId, need: 'edit'}).call()
if (ec.message.hasError()) return
const name = String(contentFile.getName ? contentFile.getName() : contentFile.name || '').replace(/^.*[\/\\]/, '')
const type = String(contentFile.contentType || contentFile.getContentType?.() || '')
// the file is served inline by its name's type, so the name is an image's, and the type sent, when there is one, too
if (!/\.(png|jpe?g|gif|webp)$/i.test(name) || (type && !/^image\/(png|jpe?g|pjpeg|gif|webp)$/i.test(type))) {
    ec.message.addError(L('Choose an image file: PNG, JPEG, GIF or WebP')); return }
if (Number(contentFile.size ?? contentFile.getSize?.() ?? 0) > 5 * 1024 * 1024) { ec.message.addError(L('The photo may be at most 5 MB')); return }
partyContentId = ec.service.sync().name('mantle.party.PartyServices.create#PartyContent').parameters({partyId: partyId,
    partyContentTypeEnumId: 'PcntFaceImage', contentFile: contentFile, contentDate: ec.user.nowTimestamp, description: name}).call()?.partyContentId
if (ec.message.hasError() || !partyContentId) return
ec.service.sync().name('ironstone.commons.ContactServices.remove#ContactAvatar').parameters({partyId: partyId, keepPartyContentId: partyContentId}).call()

removedCount = 0
ec.service.sync().name('ironstone.commons.ContactServices.check#ContactAccess').parameters({partyId: partyId, need: 'edit'}).call()
if (ec.message.hasError()) return
const folder = `/party/${partyId}/content_`
for (const content of ec.entity.find('mantle.party.PartyContent').condition('partyId', partyId)
        .condition('partyContentTypeEnumId', 'PcntFaceImage').list()) {
    if (keepPartyContentId && content.partyContentId === keepPartyContentId) continue
    const location = content.contentLocation ? String(content.contentLocation) : null
    ec.service.sync().name('delete#mantle.party.PartyContent').parameter('partyContentId', content.partyContentId).call()
    if (ec.message.hasError()) return
    removedCount++
    if (!location || !location.includes(folder + content.partyContentId + '/')) continue
    try {
        const ref = ec.resource.getLocationReference(location)
        if (ref && ref.getExists()) ref.delete()
    } catch (err) {
        ec.logger.warn(`The photo of party ${partyId}: the row of ${location} is removed, the file was not: ${err}`)
    }
}

contentLocation = null
const access = ec.service.sync().name('ironstone.commons.ContactServices.check#ContactAccess').parameters({partyId: partyId}).call()
if (!access?.visible) return
const content = ec.entity.find('mantle.party.PartyContent').condition('partyId', partyId).condition('partyContentTypeEnumId', 'PcntFaceImage')
        .orderBy('-contentDate,-partyContentId').limit(1).list()
contentLocation = content.length ? (content[0].contentLocation || null) : null

ec.service.sync().name('ironstone.commons.ContactServices.check#ContactAccess').parameters({partyId: partyId, need: 'view'}).call()
if (ec.message.hasError()) return
if (remove) {
    ec.service.sync().name('mantle.party.ContactBookServices.remove#ContactBookParties').parameters({contactBookId: contactBookId, partyId: partyId}).call()
    return
}
const textList = (value) => value == null ? [] : (typeof value === 'string' ? value.split(',') : Array.from(value)).map((item) => String(item).trim()).filter((item) => item)
const wanted = textList(contactBookGroupIdList)
const out = ec.service.sync().name('mantle.party.ContactBookServices.add#ContactBookParties').parameters({contactBookId: contactBookId,
    partyId: partyId, contactBookGroupIdList: wanted}).call()
if (ec.message.hasError()) return
if (out?.failedPartyIdList?.length) { ec.message.addError(ec.l10n.localize('The contact could not be added to that book')); return }
// out of the book's groups not chosen
for (const group of ec.entity.find('mantle.party.contact.ContactBookGroup').condition('contactBookId', contactBookId).list()) {
    if (wanted.includes(group.contactBookGroupId)) continue
    if (ec.entity.find('mantle.party.contact.ContactBookGroupParty').condition('contactBookGroupId', group.contactBookGroupId).condition('partyId', partyId).count() === 0) continue
    ec.service.sync().name('mantle.party.ContactBookServices.remove#ContactBookGroupParties').parameters({contactBookGroupId: group.contactBookGroupId,
        partyId: partyId}).call()
    if (ec.message.hasError()) return
}

location = null
if (!ec.user.userId) { ec.message.addError(ec.l10n.localize('An export needs a user')); return }
const textList = (value) => value == null ? [] : (typeof value === 'string' ? value.split(',') : Array.from(value)).map((item) => String(item).trim()).filter((item) => item)
const ids = Array.from(new Set(textList(partyIdList).concat(textList(partyId))))
if (!contactBookId && !ids.length) { ec.message.addError(ec.l10n.localize('Select one or more contacts first')); return }
const out = ec.service.sync().name('mantle.party.ContactImportServices.export#Contacts').parameters({contactBookId: contactBookId || null,
    contactBookGroupId: contactBookGroupId || null, partyIdList: contactBookId ? null : ids, format: format === 'csv' ? 'csv' : 'vcard'}).call()
if (ec.message.hasError()) return
exportedCount = out.exportedCount || 0
fileName = out.fileName || (format === 'csv' ? 'contacts.csv' : 'contacts.vcf')
if (!contactBookId && ids.length === 1 && exportedCount === 1) {
    // one contact: the file is named after it
    const rows = ec.service.sync().name('ironstone.commons.ContactServices.get#ContactRows').parameters({partyIdList: ids}).call()?.rowList || []
    const base = rows.length ? String(rows[0].name).replace(/[^A-Za-z0-9._-]+/g, '-').replace(/^-+|-+$/g, '') : ''
    if (base) fileName = base + (format === 'csv' ? '.csv' : '.vcf')
}
location = `dbresource://ironstone/ContactExport/${ec.user.userId}/${fileName}`
ec.resource.getLocationReference(location).putText(out.fileText || '')

canMerge = false
fieldList = []
keepOptions = []
const L = (text) => ec.l10n.localize(text)
if (partyId === otherPartyId) { ec.message.addError(L('Choose two different contacts')); return }
const records = []
for (const id of [partyId, otherPartyId]) {
    const out = ec.service.sync().name('ironstone.commons.ContactServices.get#ContactRecord').parameters({partyId: id}).call()
    if (ec.message.hasError()) return
    if (!out?.found) { ec.message.addError(ec.resource.expand('Contact ${partyId} not found', '', {partyId: id})); return }
    const internal = ec.entity.find('mantle.party.PartyRole').condition('partyId', id).condition('roleTypeId', 'OrgInternal').count() > 0
    records.push(Object.assign({}, out.record, {access: out.access, internal: internal,
        emails: (out.contactMechList || []).filter((mech) => mech.kind === 'email').map((mech) => mech.value).join(', '),
        phones: (out.contactMechList || []).filter((mech) => mech.kind === 'phone').map((mech) => mech.value).join(', '),
        websites: (out.contactMechList || []).filter((mech) => mech.kind === 'web').map((mech) => mech.value).join(', '),
        addresses: (out.addressList || []).map((address) => address.oneLine).join(' | '),
        organizations: (out.organizationList || []).map((org) => [org.jobTitle, org.organizationName].filter((part) => part).join(' · ')).join(', '),
        books: (out.bookList || []).map((book) => book.contactBookName).join(', '),
        roles: (out.roleList || []).map((role) => role.description).join(', ')}))
}
left = records[0]
right = records[1]
const isOrg = left.isOrganization
if (left.isOrganization !== right.isOrganization) { reason = L('A person and an organization cannot be merged'); }
// the fields a merge may take from either side, then what the merge brings together
const choice = isOrg ? [['organizationName', 'Name']] : [['firstName', 'First name'], ['middleName', 'Middle name'], ['lastName', 'Last name'],
    ['nickname', 'Nickname'], ['personalTitle', 'Title'], ['suffix', 'Suffix'], ['birthDate', 'Birthday']]
choice.push(['comments', 'Comments'])
for (const [name, label] of choice) {
    const a = left[name] == null ? '' : String(left[name])
    const b = right[name] == null ? '' : String(right[name])
    if (!a && !b) continue
    fieldList.push({fieldName: name, label: L(label), left: a, right: b, differs: a !== b, choosable: a !== b && !!a && !!b})
}
for (const [name, label] of [['emails', 'Email'], ['phones', 'Phone'], ['websites', 'Website'], ['addresses', 'Addresses'],
        ['organizations', 'Organization and title'], ['books', 'Books'], ['roles', 'Roles']]) {
    if (!left[name] && !right[name]) continue
    fieldList.push({fieldName: name, label: L(label), left: left[name] || '', right: right[name] || '', differs: left[name] !== right[name], choosable: false, combined: true})
}
if (reason) return
// Mantle's merge guards (impl-sales P3): who may merge this way and whether the pair may be merged at all
const guards = {}
const guarded = (keep, gone) => guards[keep.partyId] || (guards[keep.partyId] = ec.service.sync()
        .name('mantle.party.DuplicateServices.check#PartyMerge').parameters({toPartyId: keep.partyId, fromPartyId: gone.partyId}).call() || {})
const canKeep = (keep, gone) => !gone.internal && !(keep.access.isPersonal && !gone.access.isPersonal) && guarded(keep, gone).allowed
        && ((keep.access.canEdit && gone.access.canEdit) || guarded(keep, gone).admittedBy === 'sales')
if (canKeep(left, right)) keepOptions.push({key: left.partyId, text: ec.resource.expand('Keep ${name} (${id})', '', {name: left.name, id: left.pseudoId})})
if (canKeep(right, left)) keepOptions.push({key: right.partyId, text: ec.resource.expand('Keep ${name} (${id})', '', {name: right.name, id: right.pseudoId})})
canMerge = keepOptions.length > 0
const refused = [guarded(left, right), guarded(right, left)].find((found) => found.reasonCode && found.reasonCode !== 'PERMISSION_DENIED')
if (!canMerge && refused) reason = refused.message
else if (!canMerge) reason = !left.access.canEdit || !right.access.canEdit ? L('You may not change both contacts')
    : L('A directory contact is not merged into a personal contact: link the personal contact to the directory instead')

const pair = ec.service.sync().name('ironstone.commons.ContactServices.get#ComparePair').parameters({partyId: keepPartyId, otherPartyId: otherPartyId}).call()
if (ec.message.hasError()) return
if (!(pair.keepOptions || []).some((option) => option.key === keepPartyId)) { ec.message.addError(pair.reason || ec.l10n.localize('These contacts cannot be merged this way')); return }
const take = (takeFields ? String(takeFields).split(',') : []).map((name) => name.trim()).filter((name) => name)
const allowed = new Set((pair.fieldList || []).filter((field) => !field.combined).map((field) => field.fieldName))
const updates = {}
for (const name of take) if (allowed.has(name) && pair.right[name]) updates[name] = pair.right[name]
if (Object.keys(updates).length) {
    // a merger Mantle's guards admit without the contact edit (a Sales manager, impl-sales P3) takes the chosen names
    // as the merge's own change, through the same Mantle service update#Contact calls
    if (pair.left.access.canEdit) ec.service.sync().name('ironstone.commons.ContactServices.update#Contact').parameters(Object.assign({partyId: keepPartyId}, updates)).call()
    else ec.service.sync().name('mantle.party.PartyServices.update#PartyDetail').parameters(Object.assign({partyId: keepPartyId}, updates)).call()
    if (ec.message.hasError()) return
}
if (pair.right.access.isPersonal && !pair.left.access.isPersonal) {
    ec.service.sync().name('mantle.party.ContactBookServices.link#PersonalContactToDirectory').parameters({partyId: otherPartyId,
        targetPartyId: keepPartyId}).call()
} else {
    ec.service.sync().name('mantle.party.DuplicateServices.merge#Parties').parameters({toPartyId: keepPartyId, fromPartyId: otherPartyId}).call()
}
if (ec.message.hasError()) return
const after = ec.entity.find('mantle.party.Party').condition('partyId', otherPartyId).one()
if (after?.mergedToPartyId !== keepPartyId) { ec.message.addError(ec.resource.expand('${other} was not merged into ${keep}', '', {other: otherPartyId, keep: keepPartyId})); return }
// the kept one has no duplicate left for the scan to show, until the next one finds another
ec.service.sync().name('update#mantle.party.Party').parameters({partyId: keepPartyId, hasDuplicates: 'N'}).call()
partyId = keepPartyId

pairList = []
reasonList = []
const L = (text) => ec.l10n.localize(text)
const cf = ec.entity.conditionFactory
const directory = cf.makeCondition('privateOwnerUserId', 'equals', null)
const flagged = Array.from(ec.entity.find('mantle.party.PartyDetail').condition('hasDuplicates', 'Y').condition(directory)
        .condition(cf.makeCondition('disabled', 'not-equals', 'Y', true)).orderBy('partyId').limit(500).list())
flaggedCount = flagged.length
const visible = new Map()
const seeParty = (id) => {
    if (visible.has(id)) return visible.get(id)
    const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', id).condition(directory).one()
    const shown = party != null && party.disabled !== 'Y' ? party : null
    visible.set(id, shown)
    return shown
}
const labels = {email: L('Same email'), phone: L('Same phone'), name: L('Same name'), address: L('Same address'), identification: L('Same identification')}
const pairs = new Map()
const addPair = (a, b, why, detail, nameScore) => {
    if (a === b) return
    const [x, y] = a < b ? [a, b] : [b, a]
    const key = x + '|' + y
    let pair = pairs.get(key)
    if (pair == null) { pair = {key: key, partyId: x, otherPartyId: y, reasons: new Set(), details: new Set(), nameScore: 0}; pairs.set(key, pair) }
    pair.reasons.add(why)
    if (detail) pair.details.add(String(detail))
    if (nameScore != null) pair.nameScore = Math.max(pair.nameScore, Number(nameScore) || 0)
}
for (const party of flagged) {
    // find#PartyDuplicates is anonymous-all (the scan job's), and writes the flags again
    const out = ec.service.sync().name('mantle.party.DuplicateServices.find#PartyDuplicates').parameters({partyId: party.partyId}).call()
    if (ec.message.hasError()) {
        ec.logger.warn(`Duplicates of ${party.partyId} not found: ${ec.message.getErrorsString()}`)
        ec.message.clearErrors()
        continue
    }
    const matches = out?.matchingInfoByPartyId || {}
    for (const otherId of Object.keys(matches)) {
        for (const info of Array.from(matches[otherId] || [])) {
            // what matched, by Mantle's matchType
            if (info.matchType === 'identification') addPair(party.partyId, otherId, 'identification', info.idValue)
            else if (info.matchType === 'email') addPair(party.partyId, otherId, 'email', info.infoString)
            else if (info.matchType === 'phone') addPair(party.partyId, otherId, 'phone', [info.areaCode, info.contactNumber].filter((part) => part).join(' '))
            else if (info.matchType === 'address') addPair(party.partyId, otherId, 'address', [info.address1, info.postalCode].filter((part) => part).join(', '))
            else if (info.matchType === 'birthDate') addPair(party.partyId, otherId, 'name', null, 100)
            else if (info.matchType === 'name') addPair(party.partyId, otherId, 'name', null, info.nameScore)
        }
    }
}

const counts = {}
const rows = []
for (const pair of pairs.values()) {
    const a = seeParty(pair.partyId)
    const b = seeParty(pair.otherPartyId)
    if (a == null || b == null) continue
    const order = ['email', 'phone', 'name', 'address', 'identification']
    const reasons = order.filter((why) => pair.reasons.has(why))
    for (const why of reasons) counts[why] = (counts[why] || 0) + 1
    if (reason && !reasons.includes(reason)) continue
    const nameOf = (party) => (ec.resource.expand('PartyNameOnlyTemplate', '', party) || '').trim() || party.pseudoId || party.partyId
    const nameText = pair.reasons.has('name') && pair.nameScore ? ec.resource.expand('names ${score}% alike', '', {score: Math.round(pair.nameScore)}) : null
    rows.push({key: pair.key, partyId: a.partyId, otherPartyId: b.partyId, name: nameOf(a), otherName: nameOf(b),
        pseudoId: a.pseudoId || a.partyId, otherPseudoId: b.pseudoId || b.partyId, reason: reasons[0], reasonLabel: labels[reasons[0]],
        reasonText: reasons.map((why) => labels[why]).join(', '), detailText: Array.from(pair.details).concat(nameText ? [nameText] : []).join(', '),
        // a rough score: each reason counts, an email or identification most, a name by how alike (Mantle's nameScore)
        score: reasons.reduce((sum, why) => sum + (why === 'name' ? Math.round(15 * (pair.nameScore || 100) / 100)
            : ({email: 40, identification: 40, phone: 25, address: 20}[why] || 0)), 0)})
}
const order = ['email', 'phone', 'name', 'address', 'identification']
rows.sort((x, y) => order.indexOf(x.reason) - order.indexOf(y.reason) || y.score - x.score || x.name.localeCompare(y.name))
// the limit is per reason, as the pairs are shown in a group per reason: one limit over all of them, the email
// pairs first, left no name or address group once a database had more email pairs than the limit
const max = Math.max(1, Number(limit || 100))
const taken = {}
pairList = rows.filter((row) => (taken[row.reason] = (taken[row.reason] || 0) + 1) <= max)
reasonList = order.filter((why) => counts[why]).map((why) => ({reason: why, label: labels[why], count: counts[why]}))

const L = (text) => ec.l10n.localize(text)
let admin = true
for (const id of [partyId, otherPartyId]) {
    const access = ec.service.sync().name('ironstone.commons.ContactServices.check#ContactAccess').parameters({partyId: id, need: 'view'}).call()
    if (ec.message.hasError()) return
    if (access.isPersonal) { ec.message.addError(ec.resource.expand('Contact ${partyId} not found', '', {partyId: id})); return }
    if (!access.isContactAdmin) admin = false
}
if (partyId === otherPartyId) { ec.message.addError(L('Choose two different contacts')); return }
// a contact admin, or a merger Mantle's guards admit for the pair (a Sales manager or administrator, impl-sales P3)
if (!admin && ec.service.sync().name('mantle.party.DuplicateServices.check#PartyMerge')
        .parameters({toPartyId: partyId, fromPartyId: otherPartyId}).call()?.admittedBy !== 'sales') {
    ec.message.addError(L('Only contact admins review duplicates')); return }
ec.service.sync().name('mantle.party.DuplicateServices.mark#PartyNotDuplicate').parameters({partyId: partyId, otherPartyId: otherPartyId}).call()

migratedCount = 0
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const settings = Array.from(ec.entity.find('mantle.party.PartySetting').condition('partySettingTypeId', 'BossNotDuplicates').list())
    let failed = 0
    for (const setting of settings) {
        ec.message.pushErrors()
        try {
            for (const other of String(setting.settingValue || '').split(',').map((item) => item.trim()).filter((item) => item && item !== setting.partyId)) {
                const [lowId, highId] = setting.partyId < other ? [setting.partyId, other] : [other, setting.partyId]
                if (ec.entity.find('mantle.party.Party').condition('partyId', other).one() == null) continue
                if (ec.entity.find('mantle.party.PartyNotDuplicate').condition('partyId', lowId).condition('otherPartyId', highId).one() != null) continue
                ec.service.sync().name('create#mantle.party.PartyNotDuplicate').parameters({partyId: lowId, otherPartyId: highId,
                    decidedDate: setting.lastUpdatedStamp || ec.user.nowTimestamp, comments: 'From the IronStone Contacts setting'}).call()
                if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
                migratedCount++
            }
            setting.delete()
        } catch (err) {
            failed++
            ec.logger.error(`The not-a-duplicate setting of party ${setting.partyId} was not moved to PartyNotDuplicate: ${err && err.message ? err.message : err}`)
        } finally {
            ec.message.clearErrors()
            ec.message.popErrors()
        }
    }
    if (!failed && ec.entity.find('mantle.party.PartySettingType').condition('partySettingTypeId', 'BossNotDuplicates').one() != null
            && ec.entity.find('mantle.party.PartySetting').condition('partySettingTypeId', 'BossNotDuplicates').count() === 0)
        ec.entity.find('mantle.party.PartySettingType').condition('partySettingTypeId', 'BossNotDuplicates').deleteAll()
    if (settings.length) ec.logger.info(`IronStone Contacts: ${migratedCount} not-a-duplicate pairs moved to PartyNotDuplicate from ${settings.length} settings`)
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}

const out = ec.service.sync().name('ironstone.commons.ContactServices.get#ImportDraft').parameters({importId: importId}).call()
if (!out?.folder) { ec.message.addError(ec.l10n.localize('This import is not available; start again from the file')); return }
draft = Object.assign({}, out.draft || {}, fields || {}, {importId: importId, updated: Number(String(ec.user.nowTimestamp))})
ec.resource.getLocationReference(out.folder + '/draft.json').putText(JSON.stringify(draft))

const L = (text) => ec.l10n.localize(text)
const userId = ec.user.userId
if (!userId) { ec.message.addError(L('An import needs a user')); return }
let current = importId ? ec.service.sync().name('ironstone.commons.ContactServices.get#ImportDraft').parameters({importId: importId}).call() : null
if (!current?.found) {
    importId = String(Number(String(ec.user.nowTimestamp))) + '-' + Math.floor(Math.random() * 1e6)
    current = null
}
const hasUpload = contactFile != null && Number(contactFile.size || 0) > 0
if (!hasUpload && !current?.fileLocation) { ec.message.addValidationError(null, 'contactFile', null, L('Choose a vCard or CSV file'), null); return }
const folder = `dbresource://ironstone/ContactImport/${userId}/${importId}`
let fileName = current?.draft?.fileName || null
let fileExt = current?.draft?.fileExt || null
const charset = String(characterSet || 'UTF-8').toUpperCase()
if (hasUpload) {
    fileName = String(contactFile.getName ? contactFile.getName() : contactFile.name || 'contacts')
    const read = ec.service.sync().name('mantle.party.ContactImportServices.read#ContactFileText').parameters({contactFile: contactFile,
        characterSet: charset}).call()
    if (ec.message.hasError()) return
    const text = String(read?.text ?? '')
    fileExt = /\.vcf$|\.vcard$/i.test(fileName) || /^\s*BEGIN:VCARD/i.test(text) ? 'vcf' : 'csv'
    ec.resource.getLocationReference(`${folder}/source.${fileExt}`).putText(text)
}
const fileLocation = `${folder}/source.${fileExt}`
const preset = ['google', 'outlook', 'generic'].includes(presetId) && fileExt === 'csv' ? presetId : null
const parsed = ec.service.sync().name('mantle.party.ContactImportServices.parse#ContactFile').parameters({fileLocation: fileLocation,
    fileName: fileExt === 'vcf' ? 'source.vcf' : 'source.csv', presetId: preset, sampleSize: 3}).call()
if (ec.message.hasError()) return
rowCount = parsed.rowCount || 0
fileKind = parsed.fileKind
if (!rowCount) { ec.message.addError(L('The file has no contacts')); return }
ec.resource.getLocationReference(folder + '/draft.json').putText(JSON.stringify(Object.assign({}, current?.draft || {}, {importId: importId,
    fileName: fileName, fileExt: fileExt, fileKind: parsed.fileKind, presetId: parsed.presetId, chosenPresetId: presetId || null,
    characterSet: charset, rowCount: rowCount, columnMapping: parsed.columnMapping || {}, result: null, status: 'source',
    created: current?.draft?.created || Number(String(ec.user.nowTimestamp))})))

const L = (text) => ec.l10n.localize(text)
running = false
const current = ec.service.sync().name('ironstone.commons.ContactServices.get#ImportDraft').parameters({importId: importId}).call()
if (!current?.found || !current.fileLocation) { ec.message.addError(L('This import is not available; start again from the file')); return }
const draft = current.draft
if (draft.status === 'done') { result = draft.result; return }
if (draft.status === 'running') { running = true; return }
const options = draft.options || {}
if (options.asPersonal === false && !(ec.user.hasPermission('CONTACT_ADMIN') || ec.user.isInGroup('BOSS_CONTACT_ADMIN') || ec.user.isInGroup('ADMIN'))) {
    ec.message.addError(L('Only contact admins import into the directory')); return }
const inBackground = background != null ? !!background : Number(draft.rowCount || 0) > 100
if (!inBackground) {
    result = ec.service.sync().name('ironstone.commons.ContactServices.run#ImportNow').parameters({importId: importId}).call()?.result || null
    return
}
ec.service.sync().name('ironstone.commons.ContactServices.store#ImportDraft').parameters({importId: importId, fields: {status: 'running',
    error: null, started: Number(String(ec.user.nowTimestamp))}}).call()
if (ec.message.hasError()) return
ec.service.async().name('ironstone.commons.ContactServices.run#ImportNow').parameters({importId: importId}).call()
running = true

const L = (text) => ec.l10n.localize(text)
const current = ec.service.sync().name('ironstone.commons.ContactServices.get#ImportDraft').parameters({importId: importId}).call()
if (!current?.found || !current.fileLocation) { ec.message.addError(L('This import is not available; start again from the file')); return }
const draft = current.draft
if (draft.status === 'done') { result = draft.result; return }
const options = draft.options || {}
const asPersonal = options.asPersonal !== false
const fail = (error) => {
    ec.logger.warn(`Contact import ${importId} of ${ec.user.userId} stopped: ${error}`)
    ec.service.sync().name('ironstone.commons.ContactServices.store#ImportDraft').parameters({importId: importId, fields: {status: 'failed',
        error: error, finished: Number(String(ec.user.nowTimestamp))}}).ignorePreviousError(true).requireNewTransaction(true).call()
}
let out = null
try {
    out = ec.service.sync().name('mantle.party.ContactImportServices.import#Contacts').parameters({fileLocation: current.fileLocation,
        fileName: draft.fileExt === 'vcf' ? 'source.vcf' : 'source.csv', presetId: draft.fileKind === 'csv' ? draft.presetId : null,
        columnMapping: draft.columnMapping || null, duplicatePolicy: options.duplicatePolicy || 'skip', asPersonal: asPersonal,
        roleTypeId: asPersonal ? null : (options.roleTypeId || 'Contact'), contactBookId: options.contactBookId || null,
        contactBookGroupIdList: options.contactBookGroupIdList || [], groupNames: options.groupNames || null,
        useFileGroups: options.useFileGroups !== false, progressUserId: ec.user.userId, progressKey: importId}).call()
} catch (err) {
    fail(String(err && err.message ? err.message : err)); throw err
}
if (ec.message.hasError()) { fail(ec.message.getErrorsString()); return }
result = {contactBookId: out.contactBookId || null, rowCount: out.rowCount || 0, createdCount: out.createdCount || 0, updatedCount: out.updatedCount || 0,
    skippedCount: out.skippedCount || 0, failedCount: out.failedCount || 0, failureList: Array.from(out.failureList || []),
    resultList: Array.from(out.resultList || []).slice(0, 1000)}
ec.service.sync().name('ironstone.commons.ContactServices.store#ImportDraft').parameters({importId: importId, fields: {status: 'done', result: result,
    error: null, finished: Number(String(ec.user.nowTimestamp))}}).call()
